import axios from "axios";

// Настраиваем базовый URL для всех запросов
const apiClient = axios.create({
  baseURL: "http://localhost:3000/api",
  headers: {
    "Content-Type": "application/json",
    "accept": "application/json",
  }
});

export const api = {
  // Получить все товары (с параметрами фильтрации)
  getProducts: async (params = {}) => {
    let response = await apiClient.get("/products", { params });
    return response.data;
  },
  
  // Получить один товар
  getProductById: async (id) => {
    let response = await apiClient.get(`/products/${id}`);
    return response.data;
  },
  
  // Создать товар
  createProduct: async (product) => {
    let response = await apiClient.post("/products", product);
    return response.data;
  },
  
  // Обновить товар
  updateProduct: async (id, productData) => {
    let response = await apiClient.patch(`/products/${id}`, productData);
    return response.data;
  },
  
  // Удалить товар
  deleteProduct: async (id) => {
    await apiClient.delete(`/products/${id}`);
  }
};
